SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `ymwl_addon`;
CREATE TABLE `ymwl_addon` (
                              `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '主键',
                              `title` varchar(250) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '中文名',
                              `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件名或标识',
                              `no` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件唯一码',
                              `thumb` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '封面',
                              `scope` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '组别',
                              `description` text COLLATE utf8mb4_unicode_ci COMMENT '插件描述',
                              `author` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '作者',
                              `version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '本地版本号',
                              `build` datetime DEFAULT NULL COMMENT '本地构建号',
                              `net_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '互联网版本号',
                              `net_build` datetime DEFAULT NULL COMMENT '互联网构建号',
                              `requires` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT ' ' COMMENT '需求版本',
                              `website` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '网址',
                              `is_hook` tinyint(1) NOT NULL DEFAULT '0' COMMENT '钩子[0:不支持;1:支持]',
                              `is_admin` tinyint(1) NOT NULL DEFAULT '0',
                              `is_index` tinyint(1) NOT NULL DEFAULT '0',
                              `install` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否安装0未安装1已安装',
                              `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态[-1:删除;0:禁用;1启用]',
                              `create_time` bigint(20) DEFAULT NULL COMMENT '创建时间',
                              `update_time` bigint(20) DEFAULT NULL COMMENT '修改时间',
                              PRIMARY KEY (`id`) USING BTREE,
                              UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公用_插件表';


DROP TABLE IF EXISTS `ymwl_admin`;
CREATE TABLE `ymwl_admin` (
                              `admin_id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '管理员ID',
                              `username` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管理员用户名',
                              `pwd` varchar(70) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '管理员密码',
                              `salt` varchar(12) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
                              `group_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '分组ID',
                              `role_id` mediumint(8) unsigned NOT NULL DEFAULT '0' COMMENT '角色ID',
                              `parent_id` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '直属上级ID',
                              `email` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '邮箱',
                              `wechat` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系微信',
                              `realname` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '真实姓名',
                              `phone` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '联系电话',
                              `ip` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP地址',
                              `add_time` bigint(16) unsigned DEFAULT NULL COMMENT '添加时间',
                              `allocate_time` bigint(16) unsigned DEFAULT NULL COMMENT '分配时间',
                              `is_open` tinyint(2) DEFAULT '1' COMMENT '审核状态1启用',
                              `avatar` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '头像',
                              `mubiao` float(10,2) DEFAULT NULL COMMENT '当月目标业绩',
                              `ticheng` float(10,2) DEFAULT NULL COMMENT '提成点%',
                              `curgetnum` int(11) DEFAULT '0' COMMENT '当前用户使用抢的次数',
                              `curmaxnum` int(11) DEFAULT NULL COMMENT '用户当前抢的最大值',
                              `isphone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '1' COMMENT '手机号查看权限',
                              PRIMARY KEY (`admin_id`) USING BTREE,
                              KEY `username` (`username`) USING BTREE,
                              KEY `is_open` (`is_open`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='后台管理员';

