DROP TABLE IF EXISTS `ymwl_auth_rule`;
CREATE TABLE `ymwl_auth_rule` (
                                  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT,
                                  `href` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
                                  `title` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
                                  `type` tinyint(1) NOT NULL DEFAULT '1',
                                  `status` tinyint(1) NOT NULL DEFAULT '1',
                                  `authopen` tinyint(2) NOT NULL DEFAULT '1' COMMENT '是否验证权限1是0否',
                                  `icon` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '图标',
                                  `condition` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
                                  `plugin` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '插件标识',
                                  `pid` int(5) NOT NULL DEFAULT '0' COMMENT '父节点ID',
                                  `sort` int(11) NOT NULL DEFAULT '0' COMMENT '排序',
                                  `addtime` bigint(16) NOT NULL DEFAULT '0' COMMENT '添加时间',
                                  `menustatus` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否作为菜单显示1显示0不显示',
                                  `target` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '_self' COMMENT '链接打开方式',
                                  PRIMARY KEY (`id`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='权限节点';

