DROP TABLE IF EXISTS `ymwl_system_field`;
CREATE TABLE `ymwl_system_field` (
                                     `id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
                                     `name` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '字段名称[show:1,edit:1,search:1,total:0]' COLLATE 'utf8mb4_unicode_ci',
                                     `xsname` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '显示名称' COLLATE 'utf8mb4_unicode_ci',
                                     `field` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '字段名{input}[show:1,edit:1,search:1,total:0]' COLLATE 'utf8mb4_unicode_ci',
                                     `type` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '字段类型{select}(tinyint,smallint,mediumint,int,integer,bigint,double,float,decimal,numeric,char,varchar,datetime,tinytext,text,mediumtext,longtext)[show:1,edit:1,search:1,total:0]' COLLATE 'utf8mb4_unicode_ci',
                                     `rule` VARCHAR(300) NOT NULL DEFAULT '' COMMENT '验证规则' COLLATE 'utf8mb4_unicode_ci',
                                     `msg` VARCHAR(300) NOT NULL DEFAULT '' COMMENT '错误提示' COLLATE 'utf8mb4_unicode_ci',
                                     `lang` VARCHAR(10) NOT NULL DEFAULT '' COMMENT '字段长度[show:1,edit:1,search:0,total:0]' COLLATE 'utf8mb4_unicode_ci',
                                     `is_null` INT(1) NOT NULL DEFAULT '0' COMMENT '是空{switch}(1:开启,0:关闭)[show:1,edit:1,search:0,total:0,sort:100,export:0,default:0]',
                                     `create_time` BIGINT(20) NULL DEFAULT NULL COMMENT '创建时间{datetime}[show:1,edit:0,search:0,total:0,sort:100,export:0]',
                                     `update_time` BIGINT(20) NULL DEFAULT NULL COMMENT '更新时间{datetime}[show:0,edit:0,search:0,total:0,sort:100,export:0]',
                                     `formtype` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '表单类型{select}(input:单行文本,textarea:多行文本,file:单文件,files:多文件,img:单图片,imgs:多图片,video:视频,radio:单选框,checkbox:多选框,select:下拉框,color:颜色,editor:编辑框,none:隐藏框,password:密码框,optgroup:下拉组,switch:开关,json:json数组,lradio:联动单选框,lcheckbox:联动多选框,lselect:联动下拉框,datetime:时间,aselect:ajax联动下拉框,aselectgroup:ajax联动下拉组)[show:1,edit:0,sort:100,status:1]' COLLATE 'utf8mb4_unicode_ci',
                                     `table` VARCHAR(200) NOT NULL DEFAULT '' COMMENT '表名称[show:1,edit:1,search:0,total:0,sort:100,export:0]' COLLATE 'utf8mb4_unicode_ci',
                                     `show` INT(1) NOT NULL DEFAULT '0' COMMENT '到表格{switch}(0:不显示,1:显示)[show:1,edit:1,search:0,total:0,sort:100,export:0]',
                                     `open_sort` TINYINT(4) NOT NULL DEFAULT '0' COMMENT '列表排序',
                                     `edit` INT(1) NOT NULL DEFAULT '0' COMMENT '表单{switch}(0:关闭,1:开启)[show:1,edit:1,search:0,total:0,sort:100,export:0]',
                                     `search` INT(1) NOT NULL DEFAULT '0' COMMENT '搜索{switch}(0:关闭,1:开启)[show:1,edit:1,search:0,total:0,sort:100,export:0]',
                                     `total` INT(1) NOT NULL DEFAULT '0' COMMENT '合计{switch}(0:关闭,1:开启)[show:1,edit:1,search:0,total:0,sort:100,export:0]',
                                     `export` INT(1) NOT NULL DEFAULT '0' COMMENT '导出{switch}(0:关闭,1:开启)[show:1,edit:1,search:0,total:0,sort:100,export:0]',
                                     `sort` FLOAT NOT NULL DEFAULT '100' COMMENT '排序',
                                     `option` MEDIUMTEXT NULL DEFAULT NULL COMMENT '选项' COLLATE 'utf8mb4_unicode_ci',
                                     `join_table` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '链接表{lselect}[show:1,edit:1,search:0,total:0,sort:100,export:0,join_table:system_model]' COLLATE 'utf8mb4_unicode_ci',
                                     `default` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '默认值' COLLATE 'utf8mb4_unicode_ci',
                                     `foreign_key` VARCHAR(255) NOT NULL DEFAULT 'name' COMMENT '外键[show:1,edit:1]' COLLATE 'utf8mb4_unicode_ci',
                                     `describe` VARCHAR(3000) NOT NULL DEFAULT '' COMMENT '描述{textarea}' COLLATE 'utf8mb4_unicode_ci',
                                     `href` VARCHAR(255) NOT NULL DEFAULT '/admin/ajax/ajaxselect' COMMENT 'ajax下拉请求地址' COLLATE 'utf8mb4_unicode_ci',
                                     `relationship_primary_key` VARCHAR(255) NOT NULL DEFAULT 'id' COMMENT '关系主键' COLLATE 'utf8mb4_unicode_ci',
                                     `grid` VARCHAR(30) NOT NULL DEFAULT '' COMMENT '栅格布局的类列表' COLLATE 'utf8mb4_unicode_ci',
                                     `is_key` INT(1) NOT NULL DEFAULT '0' COMMENT '是否主键',
                                     `width` INT(11) NOT NULL DEFAULT '150' COMMENT '表格宽度{input}[sort:100,default:150,foreign_key:name,status:1]',
                                     `issystem` TINYINT(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT '系统字段无法修改删除',
                                     `edit_readonly` TINYINT(3) UNSIGNED NOT NULL DEFAULT '0' COMMENT '数据编辑状态是否只读0不是只读1只读',
                                     `jscol` TEXT NULL DEFAULT NULL COLLATE 'utf8mb4_unicode_ci',
                                     `addinput` TEXT NULL DEFAULT NULL COLLATE 'utf8mb4_unicode_ci',
                                     `editinput` TEXT NULL DEFAULT NULL COLLATE 'utf8mb4_unicode_ci',
                                     `status` VARCHAR(50) NOT NULL DEFAULT '' COMMENT '状态记录' COLLATE 'utf8mb4_unicode_ci',
                                     PRIMARY KEY (`id`) USING BTREE,
                                     INDEX `table` (`table`) USING BTREE,
                                     INDEX `show` (`show`) USING BTREE,
                                     INDEX `edit` (`edit`) USING BTREE
)
    COMMENT='字段表'
    COLLATE='utf8mb4_unicode_ci'
    ENGINE=MyISAM
    ROW_FORMAT=DYNAMIC
;

